        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IChallengeGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.EventDescription, out var EventDescriptionInfo))
            {
                yield return EventDescriptionInfo;
            }
            foreach (var item in obj.PreRequisites)
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (FormLinkInformation.TryFactory(obj.ScoreFormList, out var ScoreFormListInfo))
            {
                yield return ScoreFormListInfo;
            }
            if (obj.Conditions is {} ConditionsItem)
            {
                foreach (var item in ConditionsItem.WhereCastable<IConditionGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            yield break;
        }
        
