                        this.PreRequisites = BinaryOverlayList.FactoryByArray<IFormLinkGetter<IFallout76MajorRecordGetter>>(
                            mem: stream.RemainingMemory,
                            package: _package,
                            getter: (s, p) => FormLinkBinaryTranslation.Instance.OverlayFactory<IFallout76MajorRecordGetter>(p, s),
                            locs: ParseRecordLocations(
                                stream: stream,
                                constants: _package.MetaData.Constants.SubConstants,
                                trigger: RecordTypes.ANAM,
                                skipHeader: true,
                                translationParams: translationParams));
                        return new ParseResult((int)Challenge_FieldIndex.PreRequisites, type);
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)Challenge_FieldIndex.PreRequisites)
                    {
                        _ANAM2Location = (stream.Position - offset);
                        return new ParseResult((int)Challenge_FieldIndex.ANAM2, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                this.PreRequisites = BinaryOverlayList.FactoryByArray<IFormLinkGetter<IFallout76MajorRecordGetter>>(
                                    mem: stream.RemainingMemory,
                                    package: _package,
                                    getter: (s, p) => FormLinkBinaryTranslation.Instance.OverlayFactory<IFallout76MajorRecordGetter>(p, s),
                                    locs: ParseRecordLocations(
                                        stream: stream,
                                        constants: _package.MetaData.Constants.SubConstants,
                                        trigger: RecordTypes.ANAM,
                                        skipHeader: true,
                                        translationParams: translationParams));
                                return new ParseResult((int)Challenge_FieldIndex.PreRequisites, type);
                            }
                            case 1:
                            {
                                _ANAM2Location = (stream.Position - offset);
                                return new ParseResult((int)Challenge_FieldIndex.ANAM2, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.NEXT:
                {
                    _NEXTLocation = (stream.Position - offset);
                    return (int)Challenge_FieldIndex.NEXT;
                }
                case RecordTypeInts.JASF:
                {
                    _JASFLocation = (stream.Position - offset);
                    return (int)Challenge_FieldIndex.JASF;
                }
                case RecordTypeInts.SCFL:
                {
                    _ScoreFormListLocation = (stream.Position - offset);
                    return (int)Challenge_FieldIndex.ScoreFormList;
                }
                case RecordTypeInts.MNAM:
                {
                    _MNAMLocation = (stream.Position - offset);
                    return (int)Challenge_FieldIndex.MNAM;
                }
                case RecordTypeInts.RNAM:
                {
                    _RNAMLocation = (stream.Position - offset);
                    return (int)Challenge_FieldIndex.RNAM;
                }
                case RecordTypeInts.CTDA:
                case RecordTypeInts.CITC:
                {
                    this.Conditions = BinaryOverlayList.FactoryByCountPerItem<IConditionGetter>(
                        stream: stream,
                        package: _package,
                        countLength: 4,
                        trigger: Condition_Registration.TriggerSpecs,
                        countType: RecordTypes.CITC,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ConditionBinaryOverlay.ConditionFactory(new OverlayStream(s, p), p, recConv),
                        skipHeader: false);
                    return (int)Challenge_FieldIndex.Conditions;
                }
                case RecordTypeInts.CTRG:
                {
                    _CTRGLocation = (stream.Position - offset);
                    return (int)Challenge_FieldIndex.CTRG;
                }
                case RecordTypeInts.DNAM:
                {
                    _DNAMLocation = (stream.Position - offset);
                    return (int)Challenge_FieldIndex.DNAM;
                }
                case RecordTypeInts.INAM:
                {
                    _INAMLocation = (stream.Position - offset);
                    return (int)Challenge_FieldIndex.INAM;
                }
                case RecordTypeInts.SCHR:
                {
                    _SCHRLocation = (stream.Position - offset);
                    return (int)Challenge_FieldIndex.SCHR;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
